  "name": "loss_pairwise_ranknet_advantage",
  "intuition": "Use a probabilistic ranking loss (RankNet style) that models the preference probability with a sigmoid on the difference of log probabilities, weighted by the advantage gap to emphasize higher quality pair differences.",
  "pseudocode": "p = sigmoid(beta * (lpw - lpl))\nloss = -weight * advantage_gap * log(p + epsilon) - weight * (1 - advantage_gap) * log(1 - p + epsilon)\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "probabilistic_ranking",
    "signal_family": "advantage_gap",
    "link_family": "sigmoid",
    "agg_family": "mean_weighted",
    "constraint_family": "epsilon_stabilized"
  },
  "operators_used": ["sigmoid", "log", "mean", "mul", "sub", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    import torch\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', torch.ones_like(lpw))\n    advantage_gap = batch['advantage_gap']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    eps = 1e-8\n    diff = beta * (lpw - lpl)\n    prob = torch.sigmoid(diff)\n    loss = -weight * (advantage_gap * torch.log(prob + eps) + (1 - advantage_gap) * torch.log(1 - prob + eps))\n    return loss.mean()"
}

