  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_gap = batch['advantage_gap']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    eps = 1e-6\n    diff = ops.mul(beta, ops.sub(lpw, lpl))\n    prob = ops.sigmoid(diff)\n    prob = ops.clamp(prob, eps, 1 - eps)\n    log_prob = ops.log(prob)\n    log_one_minus_prob = ops.log(ops.sub(ops.ones_like(prob), prob))\n    loss = ops.mul(weight, ops.neg(ops.add(ops.mul(advantage_gap, log_prob), ops.mul(ops.sub(ops.ones_like(advantage_gap), advantage_gap), log_one_minus_prob))))\n    return ops.mean(loss)"
