{
  "name": "pairwise_cost_gap_preference",
  "intuition": "This loss encourages the model to prefer pairs where the cost difference (cost_gap) is minimized, aligning with lower-is-better objectives by penalizing larger gaps between high and low-cost options, thus promoting consistent preference for lower-cost choices.",
  "pseudocode": "loss = mean over pairs of [logsigmoid(-cost_gap * sign_difference)] where sign_difference indicates which item has lower cost, encouraging the model to assign higher probability to lower-cost options in pairwise comparisons.",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "monotonic",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid", "sign"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    import torch\n    ops = torch.nn.functional\n    log_prob_w = model_output['log_prob_w']\n    log_prob_l = model_output['log_prob_l']\n    cost_gap = batch['cost_gap']\n    weight = batch.get('weight', torch.ones_like(cost_gap))\n    sign_diff = (batch['cost_w'] < batch['cost_l']).float() * 2 - 1\n    loss_terms = -sign_diff * cost_gap\n    loss = ops.logsigmoid(-loss_terms)\n    weighted_loss = (loss * weight).mean()\n    return weighted_loss"
}

{
  "name": "loss_ranknet_advantage_exp",
  "intuition": "This loss stabilizes the RankNet-like pairwise loss by clamping the advantage_gap to a reasonable range before exponentiation to avoid numerical overflow or underflow. It also adds a small epsilon inside the log to prevent log(0). This maintains the weighting by advantage_gap while ensuring numerical stability and simpler, safer computations.",
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    advantage_gap = batch['advantage_gap']\n    beta = float(extra.get('beta', 1.0))\n    # Clamp advantage_gap to [-10, 10] to avoid numerical overflow in exp\n    adv_clamped = ops.clip(advantage_gap, -10.0, 10.0)\n    diff = lpw - lpl\n    weight_exp = ops.exp(beta * adv_clamped)\n    sigmoid_diff = ops.sigmoid(diff)\n    loss_per_pair = -weight * weight_exp * ops.log(sigmoid_diff + 1e-12)\n    return ops.mean(loss_per_pair)",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ]
  }
}

